-- German A1 Unit 5 — quantity, price and payment in one coherent shopping transaction.
-- Base content never overwrites generated audio state.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
SET @iris := (SELECT id FROM characters WHERE character_key='char-de-iris' LIMIT 1);
SET @lena := (SELECT id FROM characters WHERE character_key='char-de-lena' LIMIT 1);
SET @src := (SELECT id FROM sources WHERE source_key='src-wikibooks-de-lesson-009-shopping' LIMIT 1);
SET @unit := (SELECT id FROM units WHERE unit_key='de-a1-unit-shopping-quantity-payment' LIMIT 1);
SET @t_shop := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-shopping' LIMIT 1);
SET @t_shop_sit := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-sit-shopping' LIMIT 1);
SET @t_core := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-core-vocabulary' LIMIT 1);
SET @t_numbers := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-numbers-dates-time' LIMIT 1);
SET @t_present := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-present-verbs' LIMIT 1);
ON DUPLICATE KEY UPDATE source_id=VALUES(source_id),locator=VALUES(locator),locator_fa=VALUES(locator_fa),source_text=VALUES(source_text),source_text_hash=VALUES(source_text_hash),notes=VALUES(notes);
ON DUPLICATE KEY UPDATE language_id=VALUES(language_id),lexeme_type=VALUES(lexeme_type),surface=VALUES(surface),normalized_surface=VALUES(normalized_surface),lemma=VALUES(lemma),part_of_speech=VALUES(part_of_speech),part_of_speech_fa=VALUES(part_of_speech_fa),cefr_level=VALUES(cefr_level),translation_fa=VALUES(translation_fa),usage_note_fa=VALUES(usage_note_fa),flashcard_eligible=VALUES(flashcard_eligible);
SET @x_fleisch := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-fleisch'); SET @x_gramm := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-gramm'); SET @x_kilo := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-kilo'); SET @x_wurst := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-wurst'); SET @x_kosten := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-kosten'); SET @x_nehmen := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-nehmen'); SET @x_kasse := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-kasse'); SET @x_bezahlen := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-bezahlen'); SET @x_noch := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-noch-etwas'); SET @x_euro := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-euro');
ON DUPLICATE KEY UPDATE lexeme_id=VALUES(lexeme_id),surface=VALUES(surface),normalized_surface=VALUES(normalized_surface),form_type=VALUES(form_type),features=VALUES(features),origin=VALUES(origin),review_status=VALUES(review_status),notes=VALUES(notes);
SET @f_kostet := (SELECT id FROM lexeme_forms WHERE lexeme_form_key='lexform-de-kosten-kostet'); SET @f_nehme := (SELECT id FROM lexeme_forms WHERE lexeme_form_key='lexform-de-nehmen-nehme');
ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),unit_id=VALUES(unit_id),sequence_index=VALUES(sequence_index),position_in_unit=VALUES(position_in_unit),title_fa=VALUES(title_fa),source_title=VALUES(source_title),source_title_fa=VALUES(source_title_fa),status=VALUES(status),activity_selection_rationale=VALUES(activity_selection_rationale),sequence_rationale=VALUES(sequence_rationale),template_signature=VALUES(template_signature),notes=VALUES(notes);
SET @lesson := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-shopping-quantity-payment');
SET @dialogue := (SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-shopping-quantity-payment');
ON DUPLICATE KEY UPDATE dialogue_id=VALUES(dialogue_id),position_index=VALUES(position_index),speaker_character_id=VALUES(speaker_character_id),speaker_identity_origin=VALUES(speaker_identity_origin),speaker_gender_evidence=VALUES(speaker_gender_evidence),text_target=VALUES(text_target),translation_fa=VALUES(translation_fa),learner_turn=VALUES(learner_turn);
ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id),position_index=VALUES(position_index),activity_type=VALUES(activity_type),instruction_fa=VALUES(instruction_fa),selection_reason=VALUES(selection_reason),dialogue_id=VALUES(dialogue_id),payload=VALUES(payload),transformations=VALUES(transformations),audio_text_target=VALUES(audio_text_target);
SET @a1 := (SELECT id FROM activities WHERE activity_key='act-de-a1-shopping-conversation'); SET @a2 := (SELECT id FROM activities WHERE activity_key='act-de-a1-shopping-price-matching'); SET @a3 := (SELECT id FROM activities WHERE activity_key='act-de-a1-shopping-quantity-response'); SET @a4 := (SELECT id FROM activities WHERE activity_key='act-de-a1-shopping-payment-order');
ON DUPLICATE KEY UPDATE owner_type=VALUES(owner_type),owner_key=VALUES(owner_key),surface=VALUES(surface),lexeme_id=VALUES(lexeme_id),lexeme_form_id=VALUES(lexeme_form_id),resolution_status=VALUES(resolution_status),resolution_notes=VALUES(resolution_notes);
SET @si1 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-1'); SET @si2 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-2'); SET @si3 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-3'); SET @si4 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-4'); SET @si5 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-5'); SET @si6 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-6'); SET @si7 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-7'); SET @si8 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-8'); SET @siw := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-410-wurst'); SET @sib := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-410-butter'); SET @sim := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-410-milch'); SET @sie := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-shop-410-eier');
UPDATE language_levels SET coverage=JSON_SET(coverage,'$.gaps[2]','پنج واحد نخست به بازبینی رسیده‌اند؛ مرحلهٔ بعد سفارش گسترده‌تر غذا و نوشیدنی است.'),notes='A1 همچنان در مرحلهٔ ساخت تدریجی است. پنج واحد نخست در بازبینی‌اند. مرحلهٔ بعد سفارش گسترده‌تر غذا و نوشیدنی است و باید با یک سناریوی منبع‌دار فراتر از سفارش تک‌قلمی سطح پیشین ساخته شود.' WHERE id=@level;
COMMIT;
