INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES
('src-wikibooks-de-lesson-009-shopping','Deutschkurs für Anfänger/Lektion 009','خرید واقعی‌تر: قیمت، مقدار و پرداخت','Wikibooks contributors','de','course','https://en.wikibooks.org/wiki/Deutschkurs_f%C3%BCr_Anf%C3%A4nger/Lektion_009','Items 399 and 410: coherent supermarket transaction with price, weight, additional goods, cash desk and payment, plus quantity-price practice.','بخش‌های ۳۹۹ و ۴۱۰؛ گفت‌وگوی خرید با قیمت، گرم و کیلو، کالای اضافه، صندوق و پرداخت و تمرین مقدار و قیمت.','2021-04-02','contemporary_verified','صفحهٔ زندهٔ ویکی‌بوکس در ۱۷ سپتامبر ۲۰۲۶ بررسی شد. آخرین ویرایش ثبت‌شدهٔ صفحه ۲ آوریل ۲۰۲۱ است؛ عبارت‌های انتخاب‌شده دربارهٔ قیمت، وزن، درخواست کالا، صندوق و پرداخت در بازبینی فعلی همچنان آلمانی معیار و طبیعی‌اند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Deutschkurs für Anfänger/Lektion 009','reuse_with_attribution','2026-09-17','استفاده به بخش‌های ۳۹۹ و ۴۱۰ محدود است. گفت‌وگوی ۳۹۹ تراکنش پیوستهٔ خرید را پوشش می‌دهد و تمرین ۴۱۰ دامنهٔ مقدار و قیمت را گسترش می‌دهد. فاصلهٔ چاپی پیش از نقطه در یکی از جمله‌ها فقط به نشانه‌گذاری استاندارد تبدیل می‌شود و واژگان آلمانی تغییر نمی‌کنند.') ON DUPLICATE KEY UPDATE title=VALUES(title),title_fa=VALUES(title_fa),organization_or_author=VALUES(organization_or_author),language_code=VALUES(language_code),source_type=VALUES(source_type),url=VALUES(url),locator=VALUES(locator),locator_fa=VALUES(locator_fa),published_or_updated_at=VALUES(published_or_updated_at),modernity_status=VALUES(modernity_status),currency_evidence=VALUES(currency_evidence),license_name=VALUES(license_name),license_url=VALUES(license_url),attribution_text=VALUES(attribution_text),reuse_status=VALUES(reuse_status),retrieved_at=VALUES(retrieved_at),notes=VALUES(notes);
INSERT INTO units(unit_key,language_level_id,sequence_index,title_fa,grouping_rationale,status,metadata,notes) VALUES('de-a1-unit-shopping-quantity-payment',@level,5,'خرید واقعی‌تر: مقدار، قیمت و پرداخت','سطح پیشین فقط نیاز و خرید بسیار ساده را معرفی کرده بود. این واحد همان موقعیت را به یک تراکنش واقعی‌تر گسترش می‌دهد: قیمت، مقدار، افزودن کالا، پایان سفارش و پرداخت. گفت‌وگوی اصلی همهٔ این اجزا را پیوسته پوشش می‌دهد و تمرین مقدار و قیمت دامنهٔ کالاها را بدون ساخت جملهٔ آزاد گسترش می‌دهد.','review',JSON_OBJECT('sourceRefs',JSON_ARRAY('src-wikibooks-de-lesson-009-shopping'),'learningTargets',JSON_ARRAY('پرسیدن و فهم قیمت کالا','فهم گرم و کیلو در مقدار خرید','افزودن کالا و تعیین مقدار','فهم پرداخت در صندوق')),'بازبینی پوشش انجام شد. گفت‌وگوی هشت‌نوبتی بخش ۳۹۹ قیمت، گرم و کیلو، افزودن کالا، مقدار دوم و پرداخت در صندوق را پوشش می‌دهد و تمرین ۴۱۰ چند کالا و قیمت دیگر را اضافه می‌کند. برای هدف فعلی خرید A1 شکاف ضروری مستقلی برای درس دوم پیدا نشد.') ON DUPLICATE KEY UPDATE sequence_index=VALUES(sequence_index),title_fa=VALUES(title_fa),grouping_rationale=VALUES(grouping_rationale),status=IF(status='final',status,VALUES(status)),metadata=VALUES(metadata),notes=VALUES(notes);
