INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes) VALUES
('de-a1-lesson-shopping-quantity-payment',@level,@unit,9,1,'چقدر می‌خواهید؟','Wie viel kostet dieses Fleisch? / Wie viel möchten Sie?','این گوشت چقدر است؟ / چه مقدار می‌خواهید؟','draft','گفت‌وگوی کامل تراکنش را در بافت می‌آورد؛ تطبیق چهار کالای دیگر مقدار را به قیمت وصل می‌کند، انتخاب پاسخ مقدار فهم نوبت فروشنده را می‌سنجد و مرتب‌سازی جملهٔ پرداخت آخرین مرحلهٔ خرید را فعال می‌کند.','درس از مشارکت در یک تراکنش واقعی به خواندن مقدار و قیمت، انتخاب پاسخ مناسب و در پایان بازیابی هدایت‌شدهٔ دستور پرداخت حرکت می‌کند.','conversation_speaking>matching>choose_response>word_order','blocked_until_level_final','یک گفت‌وگوی منبع‌دار هشت‌نوبتی هستهٔ کل واحد خرید را می‌سازد.')
