INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES('dlg-de-a1-shopping-quantity-payment',@level,'آیریس در فروشگاه از لنا قیمت گوشت را می‌پرسد، مقدار می‌خواهد، سوسیس هم اضافه می‌کند و در پایان راهنمای پرداخت در صندوق را می‌شنود.','learner','هشت نوبت بخش ۳۹۹ یک تراکنش کامل و طبیعی می‌سازند: سؤال قیمت، پاسخ قیمت، درخواست مقدار، افزودن کالا، تعیین مقدار دوم، پایان سفارش و پرداخت. فقط فاصلهٔ چاپی پیش از نقطه در یک نوبت به نشانه‌گذاری معمول تبدیل شده است.') ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),scenario=VALUES(scenario),opening_initiator=VALUES(opening_initiator),scene_quality_rationale=VALUES(scene_quality_rationale);
