INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-shopping-conversation',@lesson,1,'conversation_speaking','خرید را از پرسیدن قیمت تا رسیدن به صندوق انجام بده.','گفت‌وگوی هشت‌نوبتی منبع همهٔ مراحل اصلی تراکنش این واحد را به‌صورت پیوسته دارد.',@dialogue,JSON_OBJECT('interaction','read_aloud_exchange','openingInitiator','learner'),JSON_ARRAY('verbatim_dialogue','other','persian_translation_added','character_metadata_added'),NULL,'not_required'),
('act-de-a1-shopping-price-matching',@lesson,2,'matching','هر مقدار کالا را به قیمت منبع‌دار خودش وصل کن.','چهار نمونهٔ بخش ۴۱۰ مقدارهای متفاوت و چند کالای روزمره را با قیمت واقعی تمرین پیوند می‌دهند.',NULL,JSON_OBJECT('pairs',JSON_ARRAY(JSON_OBJECT('left','300 g Wurst','leftFa','۳۰۰ گرم سوسیس','right','5,99 Euro','rightFa','۵٫۹۹ یورو'),JSON_OBJECT('left','250 g Butter','leftFa','۲۵۰ گرم کره','right','3,95 Euro','rightFa','۳٫۹۵ یورو'),JSON_OBJECT('left','zwei Flaschen Milch','leftFa','دو بطری شیر','right','2,99 Euro','rightFa','۲٫۹۹ یورو'),JSON_OBJECT('left','fünf Eier','leftFa','پنج تخم‌مرغ','right','2,67 Euro','rightFa','۲٫۶۷ یورو'))),JSON_ARRAY('source_items_grouped_for_matching','persian_translation_added'),NULL,'not_required'),
('act-de-a1-shopping-quantity-response',@lesson,3,'choose_response','فروشنده مقدار را می‌پرسد؛ پاسخ درست را انتخاب کن.','پاسخ مقدار باید از دو نوبت دیگر همان تراکنش متمایز شود.',NULL,JSON_OBJECT('promptTarget','Wie viel möchten Sie?','promptFa','چه مقدار می‌خواهید؟','options',JSON_ARRAY(JSON_OBJECT('textTarget','Bitte 250 Gramm.','translationFa','لطفاً ۲۵۰ گرم.','correct',TRUE),JSON_OBJECT('textTarget','Noch etwas?','translationFa','چیز دیگری؟','correct',FALSE),JSON_OBJECT('textTarget','Danke, das ist alles.','translationFa','ممنون، همین کافی است.','correct',FALSE))),JSON_ARRAY('options_selected_from_source_material','persian_translation_added'),NULL,'not_required'),
('act-de-a1-shopping-payment-order',@lesson,4,'word_order','دستور پرداخت را دوباره بساز.','آخرین مرحلهٔ تراکنش از فهم و خواندن به بازیابی فعال جملهٔ پرداخت منتقل می‌شود.',NULL,JSON_OBJECT('sourceText','Bezahlen Sie bitte dort.','sourceTextFa','لطفاً آنجا پرداخت کنید.','tokens',JSON_ARRAY('Bezahlen','Sie','bitte','dort.'),'answer',JSON_ARRAY('Bezahlen','Sie','bitte','dort.')),JSON_ARRAY('sentence_tokenized_for_word_order','persian_translation_added'),NULL,'not_required')
